<script lang="ts">
import type {NamedValue} from './notifications';import Icon from './Icon.svelte';
let {title,rows=$bindable(),t}:{title:string;rows:NamedValue[];t:(key:string)=>string}=$props();let revealed=$state<Record<number,boolean>>({});
function remove(index:number){rows=rows.length===1?[{name:'',value:'',secret:true}]:rows.filter((_,i)=>i!==index);revealed={};}
</script>
<section class="webhook-rows"><div class="parameter-heading"><h2>{title}</h2><button type="button" class="icon-button" aria-label={t('Добавить строку')+' · '+title} title={t('Добавить строку')} onclick={()=>rows=[...rows,{name:'',value:'',secret:true}]}><Icon name="plus"/></button></div>{#each rows as row,index}<div class="parameter-row"><label class="profile-field"><span><small>{t('Название')}</small><input aria-label={title+' · '+t('Название')+' '+(index+1)} bind:value={row.name} spellcheck="false" autocomplete="off"/></span></label><div class="profile-field"><label><small>{t('Значение')}</small><input aria-label={title+' · '+t('Значение')+' '+(index+1)} bind:value={row.value} type={row.secret&&!revealed[index]?'password':'text'} spellcheck="false" autocomplete="off"/></label><button type="button" class="icon-button" aria-label={t('Скрывать значение')} aria-pressed={row.secret} title={t('Скрывать значение')} onclick={()=>{row.secret=!row.secret;revealed[index]=false;}}><Icon name="lock" size={17}/></button>{#if row.secret}<button type="button" class="icon-button" aria-label={t('Показать значение')} aria-pressed={revealed[index]??false} title={t('Показать значение')} onclick={()=>revealed[index]=!revealed[index]}><Icon name="eye" size={17}/></button>{/if}</div><button type="button" class="icon-button" disabled={rows.length===1&&!row.name&&!row.value} title={t('Удалить строку')} aria-label={t('Удалить строку')+' '+(index+1)} onclick={()=>remove(index)}><Icon name="trash" size={18}/></button></div>{/each}</section>
